<?php
declare(strict_types=1);
namespace Hls\Controllers;
use Hls\Http\HttpError; use Hls\Http\Input; use Hls\Http\View; use Hls\Repositories\Repository; use Hls\Middleware\Access; use Hls\Services\Audit; use Hls\Services\Csrf;
final class MaintenanceCostController {
 public function __construct(private Repository $repo,private View $view,private Access $access,private Audit $audit){}
 public function rates(): void { $this->access->demand('maintenance.cost.manage'); if($_SERVER['REQUEST_METHOD']==='POST'){ Csrf::verify($_POST['csrf']??null); $branch=Input::id($_POST,'branch_id',true); if($branch)$this->access->demandBranch($branch); $code=trim((string)($_POST['rate_code']??''));$desc=trim((string)($_POST['description']??''));$rate=(float)($_POST['rate_per_hour']??-1);$from=(string)($_POST['effective_from']??'');$until=trim((string)($_POST['effective_until']??''))?:null;if($code===''||$desc===''||$rate<0||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)||($until&&!preg_match('/^\d{4}-\d{2}-\d{2}$/',$until))||($until&&$until<$from))throw new HttpError(422,'Tarif atau periode tidak valid.');$over=$this->repo->one('SELECT id FROM maintenance_cost_rates WHERE rate_code=? OR (COALESCE(branch_id,0)=COALESCE(?,0) AND active=1 AND effective_from<=COALESCE(?,"9999-12-31") AND (effective_until IS NULL OR effective_until>=?))',[$code,$branch,$until,$from]);if($over)throw new HttpError(409,'Kode atau periode tarif bertabrakan.');$this->repo->run('INSERT INTO maintenance_cost_rates(branch_id,rate_code,description,rate_per_hour,effective_from,effective_until,created_by) VALUES(?,?,?,?,?,?,?)',[$branch?:null,$code,$desc,$rate,$from,$until,(int)$this->access->user['id']]);$this->audit->record((int)$this->access->user['id'],'maintenance_cost_rate_created','maintenance_cost_rates',(int)$this->repo->db->lastInsertId(),['code'=>$code]);$this->view->redirect('/maintenance/cost-rates');} $rows=$this->repo->all('SELECT r.*,b.name branch_name FROM maintenance_cost_rates r LEFT JOIN branches b ON b.id=r.branch_id ORDER BY r.effective_from DESC');$branches=$this->repo->all('SELECT id,name FROM branches WHERE active=1 ORDER BY name');$this->view->render('maintenance-cost-rates',compact('rows','branches')); }
}
